-- SPEC 02 (specs/02-supabase-schema.md) — paso 6 del plan de implementación.
-- Seed de las 15 rutas oficiales de DevTalles (data/programs.json, ver data/SUMMARY.md) como
-- `programs`, y sus 107 vínculos curso↔paso como `program_courses`. React y Dart aportan dos
-- rutas cada uno ("React"/"React Native", "Dart móvil"/"Dart Web"); el resto, una sola.
--
-- Los dos bloques JSON de abajo salen de data/programs.json, expandiendo cada curso de un
-- paso con varios cursos (máx. 4 en el catálogo) a su propia fila de program_courses.

insert into public.programs (slug, source_slug, name, position)
select slug, source_slug, name, position
from jsonb_to_recordset($seed_programs$
[{"slug":"fundamentos","source_slug":"fundamentos","name":"Fundamentos","position":1},{"slug":"react","source_slug":"react","name":"React","position":2},{"slug":"react-native","source_slug":"react","name":"React Native","position":3},{"slug":"vue","source_slug":"vue","name":"Vue","position":4},{"slug":"angular","source_slug":"angular","name":"Angular","position":5},{"slug":"node","source_slug":"node","name":"NodeJs","position":6},{"slug":"nest","source_slug":"nest","name":"NestJS","position":7},{"slug":"dart-movil","source_slug":"dart","name":"Dart móvil","position":8},{"slug":"dart-web","source_slug":"dart","name":"Dart Web","position":9},{"slug":"python","source_slug":"python","name":"Python","position":10},{"slug":"java","source_slug":"java","name":"Java","position":11},{"slug":"csharp","source_slug":"csharp","name":"C#","position":12},{"slug":"ia","source_slug":"ia","name":"IA/Automatizaciones","position":13},{"slug":"php","source_slug":"php","name":"PHP","position":14},{"slug":"go","source_slug":"go","name":"GO","position":15}]
$seed_programs$::jsonb)
  as t(slug text, source_slug text, name text, position integer);

insert into public.program_courses (program_id, course_id, stage, level, position, note)
select p.id, c.id, t.stage, t.level::public.program_course_level, t.position, t.note
from jsonb_to_recordset($seed_links$
